function shortestRun(target: number, nums: number[]): number {
  const n = nums.length;
  const pre = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
  let best = Infinity;
  for (let i = 0; i < n; i++) {
    const need = pre[i] + target;
    let lo = i + 1, hi = n + 1; // first j in [i+1, n] with pre[j] >= need, or n+1
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pre[mid] >= need) hi = mid; else lo = mid + 1;
    }
    if (lo <= n) best = Math.min(best, lo - i);
  }
  return best === Infinity ? 0 : best;
}

